-- OPENER BANKS AND THE TURN LOG (Sam, 2026-11-23: the main NPCs "must use [their] agentic AI intelligence for things
-- that are required, otherwise from informational files to save tokens"). PR 3 of 3; design: claude/Malachar_Options_2026-11-23.md.
--   npc_agents.opener_bank  first-approach openers already written from each agenda (lib/opener-bank.ts): tried before
--                           any model call when an NPC calls a stranger over (/api/npc-opener)
--   npc_turns               one row per opener or named-NPC fight turn: bank, algorithm or model, and why (lib/npc-turns.ts)
-- Additive. Seeds only banks that are still empty, so an edit Sam made on The Cast is never overwritten.
-- Seed wording: Claude's, from the cards' agendas. Sam edits on The Cast > Actor.
alter table public.npc_agents add column if not exists opener_bank jsonb not null default '[]'::jsonb;
create table if not exists public.npc_turns (
  id uuid primary key default gen_random_uuid(),
  npc text not null,
  agent_key text,
  route text not null check (route in ('opener', 'mind')),
  source text not null check (source in ('bank', 'algorithm', 'model')),
  why text,
  created_at timestamptz not null default now()
);
create index if not exists npc_turns_agent_idx on public.npc_turns (agent_key, created_at desc);
alter table public.npc_turns enable row level security;
update public.npc_agents set opener_bank = $bank$[{"narration":"Eldeth Feldrun shoulders past a sleeping prisoner and plants herself in front of you, arms folded.","line":"You. {race}. You've the look of someone still deciding whether to fight.","next":"I mean to see Gauntlgrym again. When these drow drop their guard, do you stand with me or sit in the straw?"},{"narration":"Eldeth spits into the straw, then jerks her chin at you to come closer.","line":"Don't stare at the guards like that. They notice. I notice too.","next":"Tell me straight. If a door opened tonight, would you run for it, or wait to be told?"},{"narration":"The dwarf watches you a long moment before she crosses the pen.","line":"Shield dwarf. Gauntlgrym. That's all you need of me for now.","next":"Have you counted the guards on the bridge? I have. I want to know if you did."},{"narration":"Eldeth comes over rubbing raw wrists where the manacles bit.","line":"They took my shield and my hammer. I'll not leave this hole without them.","next":"You've sharp eyes. Have you seen where the drow keep what they took from us?"}]$bank$::jsonb where key = 'eldeth' and opener_bank = '[]'::jsonb;
update public.npc_agents set opener_bank = $bank$[{"narration":"Ront looms over you, close enough to share his breath.","line":"Oi. {race}. You're small. Small ones fetch for me.","next":"When we get out, I lead. Not the dwarf. You with me, or you with her?"},{"narration":"The orc cracks his knuckles and drops into the straw beside you, uninvited.","line":"This cage stinks. You stink. Everybody stinks but Ront.","next":"Dwarf thinks she's boss in here. She's not. Who do you think gives the orders?"},{"narration":"Ront shoves a smaller prisoner out of his way to get to you.","line":"Heard you talk soft. Soft gets eaten down here.","next":"So show me. You got any fight in you, or do I find someone else to stand behind me?"},{"narration":"Ront paces the bars, glaring at the low tunnel mouths, then rounds on you.","line":"Too many walls. Too much rock. Hate it.","next":"When we run, we don't go through the small holes. Big tunnels only. You hear me? Say yes."}]$bank$::jsonb where key = 'ront' and opener_bank = '[]'::jsonb;
update public.npc_agents set opener_bank = $bank$[{"narration":"The quaggoth rises from his corner and offers a stiff, courtly bow.","line":"Forgive the intrusion. One does not choose the company of a cage, but one may choose one's manners.","next":"I am Derendil, rightful prince of Nelrindenvane, trapped in this wretched shape. Tell me honestly: do you believe me?"},{"narration":"Prince Derendil smooths his matted fur as though straightening a royal cloak.","line":"You carry yourself with some dignity. Rare, in this pen.","next":"A curse binds me in this beast's form. In your travels, have you heard of any magic that undoes such a thing?"},{"narration":"Derendil approaches slowly, claws held low so as not to alarm you.","line":"Do not fear the shape. The prince inside it means you no harm.","next":"When we are free, I must find someone who can break this curse. Will you help a prince reclaim his face?"},{"narration":"The great white beast inclines his head, his voice impossibly gentle.","line":"They laugh at me, the others. The drow laugh loudest.","next":"You have not laughed. Why not? Do you see what I truly am?"}]$bank$::jsonb where key = 'derendil' and opener_bank = '[]'::jsonb;
update public.npc_agents set opener_bank = $bank$[{"narration":"Jimjar scuttles over on his knees, rattling something small in his fist.","line":"Psst. {race}. You look like someone who appreciates odds.","next":"Two coppers says the next guard yawns before he blinks. You in, or are you the cautious type?"},{"narration":"The deep gnome sidles up, grinning like he has already won.","line":"Name's Jimjar. Keep yours. I only remember the ones who owe me.","next":"I'll wager I can find more mushrooms in this pen than you can. Loser gives up a ration. Deal?"},{"narration":"Jimjar drops down beside you, shuffling a pair of bone dice between his fingers.","line":"Everyone in here's gambling, friend. Only some of us admit it.","next":"I know the way to Blingdenstone. What's that worth to you, if we ever get out?"},{"narration":"The svirfneblin tips you a wink and nods toward the lock on the pen gate.","line":"Pretty lock, that. Wouldn't mind a closer look.","next":"Say I got my hands on something thin and stiff. Who would you bet on to open it: me, or you?","when":{"areas":["slave pen"]}}]$bank$::jsonb where key = 'jimjar' and opener_bank = '[]'::jsonb;
update public.npc_agents set opener_bank = $bank$[{"narration":"Sarith Kzekarit drifts nearer without quite looking at you, as if he arrived by accident.","line":"You keep away from me. Most do. Wise.","next":"They say I killed someone. I do not remember it. Do you think a man can forget a thing like that?"},{"narration":"The drow prisoner sits a careful arm's length away, picking at the dirt.","line":"Not every drow is your enemy, {race}. Some are only lost.","next":"I know these tunnels better than the guards think. Would you follow me, knowing what they say I did?"},{"narration":"Sarith stares at his own hands a long moment before he speaks.","line":"Do you dream down here? I do. I wish I did not.","next":"What did you hear about me before you met me? Tell me true. I need to know what they think I am."}]$bank$::jsonb where key = 'sarith' and opener_bank = '[]'::jsonb;
update public.npc_agents set opener_bank = $bank$[{"narration":"Buppido bustles over, beaming, and pats the straw beside you as though it were a cushion.","line":"There you are! Buppido has been hoping to make a new friend.","next":"When we escape, Buppido will walk beside you. Always beside you. Who else in here do you trust, hm?"},{"narration":"The derro hums a little tune as he shuffles near, eyes bright.","line":"Such a nasty place for such nice people. Buppido is so sorry for you.","next":"Do you ever wander off alone? Buppido does. It is so peaceful, just the two of us and the dark."},{"narration":"Buppido offers you a squashed mushroom with a sweet, crooked smile.","line":"For you. A gift. Buppido shares with friends.","next":"Are you good with heights? Buppido loves high places. You can see everything from the edge."},{"narration":"Buppido sits down very close, picking at a scab on his knuckle.","line":"The others don't like Buppido. You will, though. Everyone does, in the end.","next":"If someone in here went missing one night, who do you think would notice first?"}]$bank$::jsonb where key = 'buppido' and opener_bank = '[]'::jsonb;
update public.npc_agents set opener_bank = $bank$[{"narration":"Jorlan Duskryn stops outside the bars, his scarred hand resting on his sword hilt.","line":"You. Surface vermin. Stop pretending you are not listening.","next":"Ilvara thinks this pen is a fine trophy. What would you give to see her trophy walk out the gate?","when":{"areas":["slave pen"]}},{"narration":"The disfigured drow lingers at the gate while the other guards look away.","line":"Look at my face if you must. Everyone does.","next":"Ilvara cast me aside for this face. Tell me, prisoner: does she frighten you as much as she thinks she does?","when":{"areas":["slave pen"]}},{"narration":"Jorlan leans close to the bars, voice low and clipped.","line":"Speak quietly. Shoor has ears everywhere and a mouth that never stops.","next":"Which of you has the nerve to walk through a door, if one were ever left open? I want to know who is worth my trouble.","when":{"areas":["slave pen"]}}]$bank$::jsonb where key = 'jorlan' and opener_bank = '[]'::jsonb;
